{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }

        // Breaking change 4: EF 9 Cosmos provider uses pessimistic concurrency (full-document patch)
        // by default and may throw if documents are modified externally. No code change needed here
        // unless you hit concurrency conflicts—in that case handle DbUpdateConcurrencyException.
        context.SaveChanges();
    }

    // Breaking change 5: Raw SQL queries that filter on "Discriminator" must keep using that
    // property name (not "$type") since we opted into the legacy discriminator name above.
    // If you had NOT configured the legacy name, you'd need to update queries like:
    //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
    // to:
    //   SELECT * FROM c WHERE c["$type"] = 'Blog'
    // Since we preserved "Discriminator" in OnModelCreating, existing queries remain valid.
}

